issue.body:
**Describe the bug**

1. Boot a kernel with a non-zero hotplug_size using virtio-mem
2. Resize the VM memory to use a portion of the hotplug size
3. Pause and snapshot the VM
4. Restore the VM from the snapshot with prefault=true

If I do this, the restored VM will fault in the full hotplug size, not just the allocated size. The memory allocation is only temporary, as cloud-hypervisor will release it after the restore completes. But the temporary allocation can blow past any existing memory limits on the VM.

**To Reproduce**

Here is a Go program that can be used to reproduce the problem. This program was written by Claude.

<details>
// Command ch-virtio-mem-prefault shows that restoring a Cloud Hypervisor
// snapshot with prefault faults in the whole virtio-mem region (hotplug_size),
// not only the memory the guest had plugged (hotplugged_size).
//
// It boots a guest with boot memory and a virtio-mem region, has the guest plug
// part of the region, pauses it and takes a snapshot. It then restores the
// snapshot in a new cloud-hypervisor process through PUT /api/v1/vm.restore,
// once with prefault off and once with it on, sampling the process's anonymous
// RSS from the moment it starts. Cloud Hypervisor gives the unplugged part back
// once the restore is done, so only the peak shows the problem.
//
// Expected: both restores peak at about the guest's memory, boot memory plus
// what it plugged. Actual: the prefaulted restore peaks at boot memory plus the
// whole region. With a large region (hotplug_size of tens of GiB) that is
// enough to run the host out of memory.
//
// It needs root (for /dev/kvm), a guest kernel with CONFIG_VIRTIO_MEM, and an
// initramfs whose init keeps the guest running (any idle loop will do). To be
// safe, run it in a memory-capped scope:
//
//	sudo systemd-run --scope -p MemoryMax=8G -p MemorySwapMax=0 \
//	    go run . -ch /path/to/cloud-hypervisor -kernel bzImage -initramfs initramfs.cpio.gz
//
// It exits 1 if a restore peaks above the guest's memory plus -slack MiB.
package main

import (
	"bufio"
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"flag"
	"fmt"
	"io"
	"log"
	"net"
	"net/http"
	"os"
	"os/exec"
	"path/filepath"
	"strconv"
	"strings"
	"sync"
	"time"
)

const mib = 1 << 20

func main() {
	ch := flag.String("ch", "", "cloud-hypervisor binary")
	kernel := flag.String("kernel", "", "guest kernel")
	initramfs := flag.String("initramfs", "", "guest initramfs")
	bootMiB := flag.Int64("boot", 512, "boot memory, MiB")
	hotplugMiB := flag.Int64("hotplug", 4096, "virtio-mem region (hotplug_size), MiB")
	plugMiB := flag.Int64("plug", 256, "memory the guest plugs into the region, MiB")
	slackMiB := flag.Int64("slack", 256, "RSS over the guest's memory still counted as a pass, MiB")
	flag.Parse()
	if *ch == "" || *kernel == "" || *initramfs == "" {
		flag.Usage()
		os.Exit(2)
	}
	boot, hotplug, plug := *bootMiB*mib, *hotplugMiB*mib, *plugMiB*mib
	guest := boot + plug

	work, err := os.MkdirTemp("", "ch-virtio-mem-prefault-")
	if err != nil {
		log.Fatal(err)
	}
	defer os.RemoveAll(work)
	snapshot := filepath.Join(work, "snapshot")
	if err := os.Mkdir(snapshot, 0o700); err != nil {
		log.Fatal(err)
	}

	// Boot, plug, pause, snapshot.
	vmm := start(*ch, work, "boot",
		"--kernel", *kernel, "--initramfs", *initramfs, "--cmdline", "console=hvc0",
		"--cpus", "boot=1",
		"--memory", fmt.Sprintf("size=%d,hotplug_method=virtio-mem,hotplug_size=%d", boot, hotplug),
		"--console", "file="+filepath.Join(work, "console.log"), "--serial", "off")
	vmm.put("vm.resize", map[string]any{"desired_ram": guest})
	waitFor("the guest to plug its memory", func() bool { return vmm.info().MemoryActualSize == guest })
	memory := vmm.info().Config.Memory
	vmm.put("vm.pause", nil)
	vmm.put("vm.snapshot", map[string]any{"destination_url": "file://" + snapshot})
	vmm.kill()

	// Restore without and with prefault.
	peaks := map[bool]int64{}
	for _, prefault := range []bool{false, true} {
		vmm := start(*ch, work, fmt.Sprintf("restore-prefault-%v", prefault))
		peak := sampleRSS(vmm.cmd.Process.Pid)
		vmm.put("vm.restore", map[string]any{"source_url": "file://" + snapshot, "prefault": prefault})
		waitFor("the restore", func() bool { return vmm.info().State == "Paused" })
		peaks[prefault] = peak.stop()
		vmm.kill()
	}

	version, _ := exec.Command(*ch, "--version").Output()
	fmt.Println(strings.TrimSpace(string(version)))
	fmt.Printf("memory config: size=%d hotplug_size=%d hotplugged_size=%d\n", memory.Size, memory.HotplugSize, memory.HotpluggedSize)
	fmt.Printf("guest memory (boot + plugged):            %6d MiB\n", guest/mib)
	fmt.Printf("virtio-mem region (hotplug_size):         %6d MiB\n", hotplug/mib)
	fmt.Printf("peak RssAnon during restore, prefault=off: %6d MiB\n", peaks[false]/mib)
	fmt.Printf("peak RssAnon during restore, prefault=on:  %6d MiB\n", peaks[true]/mib)
	if peaks[true] > guest+*slackMiB*mib {
		fmt.Printf("FAIL: the prefaulted restore held %d MiB, more than the guest's %d MiB: the unplugged virtio-mem region was faulted in\n",
			peaks[true]/mib, guest/mib)
		os.Exit(1)
	}
	fmt.Println("PASS: the prefaulted restore faulted in only the guest's memory")
}

// vmm is a cloud-hypervisor process and a client of its API.
type vmm struct {
	cmd    *exec.Cmd
	client *http.Client
}

// start runs cloud-hypervisor with args and waits for its API.
func start(ch, work, name string, args ...string) *vmm {
	sock := filepath.Join(work, name+".sock")
	logFile, err := os.Create(filepath.Join(work, name+".log"))
	if err != nil {
		log.Fatal(err)
	}
	cmd := exec.Command(ch, append([]string{"--api-socket", "path=" + sock}, args...)...)
	cmd.Stdout, cmd.Stderr = logFile, logFile
	if err := cmd.Start(); err != nil {
		log.Fatal(err)
	}
	v := &vmm{cmd: cmd, client: &http.Client{
		Timeout: time.Minute,
		Transport: &http.Transport{DialContext: func(ctx context.Context, _, _ string) (net.Conn, error) {
			return (&net.Dialer{}).DialContext(ctx, "unix", sock)
		}},
	}}
	waitFor("the API socket of "+name, func() bool {
		_, err := v.call(http.MethodGet, "vmm.ping", nil)
		return err == nil
	})
	return v
}

func (v *vmm) kill() {
	v.cmd.Process.Kill()
	v.cmd.Wait()
}

func (v *vmm) call(method, endpoint string, body any) ([]byte, error) {
	var r io.Reader
	if body != nil {
		b, err := json.Marshal(body)
		if err != nil {
			return nil, err
		}
		r = bytes.NewReader(b)
	}
	req, err := http.NewRequest(method, "http://localhost/api/v1/"+endpoint, r)
	if err != nil {
		return nil, err
	}
	req.Header.Set("Content-Type", "application/json")
	resp, err := v.client.Do(req)
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()
	data, err := io.ReadAll(resp.Body)
	if err != nil {
		return nil, err
	}
	if resp.StatusCode >= 300 {
		return nil, fmt.Errorf("%s %s: %s %s", method, endpoint, resp.Status, data)
	}
	return data, nil
}

func (v *vmm) put(endpoint string, body any) {
	if _, err := v.call(http.MethodPut, endpoint, body); err != nil {
		log.Fatal(err)
	}
}

type vmInfo struct {
